 internal sealed class ExtBrowserWindow:Window {
  internal readonly ComboBox Sources=new ComboBox{MinWidth=150,Height=30},Volumes=new ComboBox{MinWidth=150,Height=30};internal readonly DataGrid Files=new DataGrid{AutoGenerateColumns=false,IsReadOnly=true,CanUserAddRows=false,CanUserDeleteRows=false,CanUserResizeColumns=false,SelectionMode=DataGridSelectionMode.Extended,HeadersVisibility=DataGridHeadersVisibility.Column,MinColumnWidth=0};
  Button openLeft,openRight;
  internal readonly TextBox Address=new TextBox{IsReadOnly=true,Height=30,Text="/",VerticalContentAlignment=VerticalAlignment.Center};internal readonly TextBlock Status=CopyUi.Label("");internal readonly Button Scan,Copy,Preview;readonly Button refresh,image,up,cancel,admin;readonly ObservableCollection<ExtSource> sources=new ObservableCollection<ExtSource>();CancellationTokenSource operation;bool busy,changing;string current="/";internal Task Pending;
  internal ExtBrowserWindow(Window owner){CopyUi.Style(this,owner,L.Text("ext.title"),1180);Height=800;ResizeMode=ResizeMode.CanResize;DialogGeometry.Bound(this,1180,800,800,540);var body=new DockPanel();CopyUi.SectionedSurface(this,body);var top=new StackPanel();DockPanel.SetDock(top,Dock.Top);body.Children.Add(top);top.Children.Add(new TextBlock{Text=L.Text("ext.title"),FontSize=23,FontWeight=FontWeights.SemiBold});top.Children.Add(CopyUi.Label(L.Text("ext.intro")));var sourceRow=new DockPanel{Margin=new Thickness(0,8,0,5)};refresh=CopyUi.Button(L.Text("action.refresh"),delegate{Pending=RefreshSources();});image=CopyUi.Button(L.Text("ext.image"),delegate{var picker=new Microsoft.Win32.OpenFileDialog{Filter="Raw disk images|*.img;*.raw;*.dd;*.bin;*.ext2;*.ext3;*.ext4|All files|*.*"};if(picker.ShowDialog(this)==true){try{var source=ExtDiskStream.Image(picker.FileName);sources.Add(source);Sources.SelectedItem=source;}catch(Exception ex){Status.Text=ex.Message;}}});Scan=CopyUi.Button(L.Text("ext.scan"),delegate{Pending=ScanSource();});foreach(var b in new[]{Scan,image,refresh}){DockPanel.SetDock(b,Dock.Right);sourceRow.Children.Add(b);}sourceRow.Children.Add(Sources);Sources.ItemsSource=sources;Sources.ItemTemplate=ExtDriveIconConverter.Template(false);top.Children.Add(CopyUi.Label(L.Text("ext.source")));top.Children.Add(sourceRow);top.Children.Add(CopyUi.Label(L.Text("ext.volume")));top.Children.Add(Volumes);var panelActions=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(0,4,0,0)};openLeft=CopyUi.Button(L.Text("ext.openLeft"),delegate{OpenInPanel(false);});openRight=CopyUi.Button(L.Text("ext.openRight"),delegate{OpenInPanel(true);});panelActions.Children.Add(openLeft);panelActions.Children.Add(openRight);top.Children.Add(panelActions);var pathRow=new DockPanel{Margin=new Thickness(0,10,0,10)};up=CopyUi.Button("↑",delegate{Pending=Navigate(ParentPath(current));});DockPanel.SetDock(up,Dock.Left);pathRow.Children.Add(up);pathRow.Children.Add(Address);top.Children.Add(pathRow);
   var bottom=new StackPanel{Margin=new Thickness(0,10,0,0)};DockPanel.SetDock(bottom,Dock.Bottom);body.Children.Add(bottom);Status.TextWrapping=TextWrapping.Wrap;Status.MaxHeight=66;bottom.Children.Add(Status);var actions=new DockPanel();bottom.Children.Add(actions);cancel=CopyUi.Button(L.Text("action.close"),delegate{if(busy)operation.Cancel();else Close();});DockPanel.SetDock(cancel,Dock.Right);actions.Children.Add(cancel);Copy=CopyUi.Button(L.Text("ext.copy"),delegate{Pending=CopySelected();});FluentTheme.Primary(Copy);DockPanel.SetDock(Copy,Dock.Right);actions.Children.Add(Copy);Preview=CopyUi.Button(L.Text("ext.filePreview"),delegate{Pending=PreviewSelected();});DockPanel.SetDock(Preview,Dock.Right);actions.Children.Add(Preview);admin=CopyUi.Button(L.Text("ext.admin"),delegate{try{Process.Start(new ProcessStartInfo(Process.GetCurrentProcess().MainModule.FileName,"--ext-window"){UseShellExecute=true,Verb="runas"});}catch(System.ComponentModel.Win32Exception ex){Status.Text=ex.Message;}});admin.Visibility=new WindowsPrincipal(WindowsIdentity.GetCurrent()).IsInRole(WindowsBuiltInRole.Administrator)?Visibility.Collapsed:Visibility.Visible;actions.Children.Add(admin);
   Files.Columns.Add(new DataGridTextColumn{Header=L.Text("column.name"),Binding=new Binding("Name"),Width=new DataGridLength(1,DataGridLengthUnitType.Star)});Files.Columns.Add(new DataGridTextColumn{Header=L.Text("column.size"),Binding=new Binding("DisplaySize"),Width=120});Files.Columns.Add(new DataGridTextColumn{Header=L.Text("column.date"),Binding=new Binding("DisplayDate"),Width=160});Files.Columns.Add(new DataGridTextColumn{Header=L.Text("ext.kind"),Binding=new Binding("Kind"),Width=130});var cell=new Style(typeof(TextBlock));cell.Setters.Add(new Setter(TextBlock.TextTrimmingProperty,TextTrimming.CharacterEllipsis));cell.Setters.Add(new Setter(FrameworkElement.ToolTipProperty,new Binding("Text"){RelativeSource=RelativeSource.Self}));foreach(var c in Files.Columns.OfType<DataGridTextColumn>())c.ElementStyle=cell;body.Children.Add(new Border{Child=FileSurface(),Background=CompactTheme.PanelSurface,BorderBrush=CompactTheme.Line,BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(6)});Files.SizeChanged+=delegate{if(Files.ActualWidth>440)Files.Columns[0].Width=Math.Max(100,Files.ActualWidth-440);};
   Sources.SelectionChanged+=delegate{if(changing||busy)return;Volumes.ItemsSource=null;Files.ItemsSource=null;Address.Text=current="/";Status.Text=L.Text("ext.selectScan");Update();if(Sources.SelectedItem is ExtSource)Pending=ScanSource();};Volumes.SelectionChanged+=delegate{if(!changing&&!busy&&Volumes.SelectedItem!=null){Files.ItemsSource=null;Address.Text=current="/";Pending=Navigate("/");}};Files.SelectionChanged+=delegate{Update();};Files.MouseDoubleClick+=delegate{if(!busy)Pending=OpenSelected();};Files.PreviewKeyDown+=delegate(object sender,KeyEventArgs e){if(e.Key==Key.Enter){e.Handled=true;if(!busy)Pending=OpenSelected();}else if(e.Key==Key.F3){e.Handled=true;if(!busy)Pending=PreviewSelected();}else if(e.Key==Key.F5){e.Handled=true;if(!busy)Pending=CopySelected();}else if(e.Key==Key.Back){e.Handled=true;if(!busy)Pending=Navigate(ParentPath(current));}};Loaded+=delegate{Pending=RefreshSources();};Closing+=delegate(object sender,System.ComponentModel.CancelEventArgs e){if(busy){operation.Cancel();e.Cancel=true;}};Update();
  }
  internal readonly TextBlock EmptyState=new TextBlock{TextWrapping=TextWrapping.Wrap,TextAlignment=TextAlignment.Center,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center,MaxWidth=620,Margin=new Thickness(24),IsHitTestVisible=false};
  Grid FileSurface(){var grid=new Grid();grid.Children.Add(Files);EmptyState.SetBinding(TextBlock.TextProperty,new Binding("Text"){Source=Status});var style=new Style(typeof(TextBlock));style.Setters.Add(new Setter(UIElement.VisibilityProperty,Visibility.Collapsed));var trigger=new DataTrigger{Binding=new Binding("HasItems"){Source=Files},Value=false};trigger.Setters.Add(new Setter(UIElement.VisibilityProperty,Visibility.Visible));style.Triggers.Add(trigger);EmptyState.Style=style;grid.Children.Add(EmptyState);return grid;}
  static string ParentPath(string path){int slash=path.LastIndexOf('/');return slash<=0?"/":path.Substring(0,slash);}
  ExtEntry[] Selected(){return Files.SelectedItems.Cast<ExtEntry>().Where(x=>!x.Parent).ToArray();}
  internal void OpenInPanel(bool right){var volume=Volumes.SelectedItem as ExtVolume;var source=Sources.SelectedItem as ExtSource;if(busy||source==null||volume==null||volume.Error!=null)return;var main=Owner as MainWindow;if(main==null){main=new MainWindow();main.Show();}main.OpenExtVolume(source,volume,right);Close();}
  void Update(){openLeft.IsEnabled=openRight.IsEnabled=!busy&&Volumes.SelectedItem is ExtVolume&&((ExtVolume)Volumes.SelectedItem).Error==null;Sources.IsEnabled=Volumes.IsEnabled=Scan.IsEnabled=refresh.IsEnabled=image.IsEnabled=up.IsEnabled=admin.IsEnabled=!busy;bool selected=Files.SelectedItems.Cast<ExtEntry>().Any(x=>!x.Parent&&x.Readable);Copy.IsEnabled=!busy&&selected;Preview.IsEnabled=!busy&&Selected().Length==1&&Selected()[0].Readable&&!Selected()[0].Directory;Files.IsEnabled=!busy;cancel.Content=L.Text(busy?"action.cancel":"action.close");}
  ExtRequest Request(string action){var source=Sources.SelectedItem as ExtSource;var volume=Volumes.SelectedItem as ExtVolume;if(source==null)throw new IOException(L.Text("ext.selectScan"));if(action!="scan"&&(volume==null||volume.Error!=null))throw new IOException(volume==null?L.Text("ext.noExt"):volume.Error);return new ExtRequest{Action=action,Source=source,Volume=volume,Path=current};}
  async Task Work(Func<CancellationToken,Task> run){if(busy)return;busy=true;operation=new CancellationTokenSource();Update();Status.Foreground=FluentTheme.Text;EmptyState.Foreground=FluentTheme.Text;Status.Text=L.Text("ext.working");try{await run(operation.Token);}catch(OperationCanceledException){Status.Text=L.Text("ext.cancelled");}catch(Exception ex){Status.Text=ex.Message;Status.Foreground=EmptyState.Foreground=Brushes.Firebrick;}finally{busy=false;operation.Dispose();operation=null;Update();}}
  internal async Task RefreshSources(){await Work(async token=>{var found=await Task.Run(()=>ExtDiskStream.Devices(),token);changing=true;try{sources.Clear();foreach(var s in found)sources.Add(s);Sources.SelectedIndex=found.Length>0?0:-1;Volumes.ItemsSource=null;Files.ItemsSource=null;}finally{changing=false;}Status.Text=L.Text(found.Length>0?"ext.selectScan":"ext.noUsb");});if(Sources.SelectedItem is ExtSource)await ScanSource();}
  internal Task ScanSource(){return Work(async token=>{var request=Request("scan");Volumes.ItemTemplate=ExtDriveIconConverter.Template(request.Source.Physical);Volumes.ItemsSource=null;Files.ItemsSource=null;Address.Text=current="/";var result=await Task.Run(()=>ExtReader.Call(request,token),token);changing=true;try{Volumes.ItemsSource=result.Volumes;Volumes.SelectedIndex=-1;Files.ItemsSource=null;}finally{changing=false;}var first=result.Volumes.FirstOrDefault(x=>x.Error==null);if(first==null){Status.Text=result.Volumes.Length==0?L.Text("ext.noExt"):String.Join(Environment.NewLine,result.Volumes.Select(x=>x.Error));return;}changing=true;Volumes.SelectedItem=first;changing=false;var listing=new ExtRequest{Action="list",Source=request.Source,Volume=first,Path="/"};var data=await Task.Run(()=>ExtReader.Call(listing,token),token);ShowRows("/",data.Entries);});}
  void ShowRows(string path,ExtEntry[] entries){current=path;Address.Text=path;var rows=entries.ToList();if(path!="/")rows.Insert(0,new ExtEntry{Name="[..]",Path=ParentPath(path),Directory=true,Readable=true,Parent=true});Files.ItemsSource=rows;if(rows.Count>0)Files.SelectedIndex=0;Status.Text=L.Format("ext.rows",entries.Length);Files.Dispatcher.BeginInvoke(new Action(delegate{Files.Focus();}));}
  internal Task Navigate(string path){return Work(async token=>{var request=Request("list");request.Path=ExtReader.Normal(path);var result=await Task.Run(()=>ExtReader.Call(request,token),token);ShowRows(request.Path,result.Entries);});}
  Task OpenSelected(){var row=Files.SelectedItem as ExtEntry;if(row==null||!row.Readable)return Task.FromResult(false);return row.Directory?Navigate(row.Path):PreviewSelected();}
  internal Task CopySelected(){var selected=Selected().Where(x=>x.Readable).ToArray();if(selected.Length==0)return Task.FromResult(false);using(var picker=new System.Windows.Forms.FolderBrowserDialog{Description=L.Text("ext.target")}){if(picker.ShowDialog()!=System.Windows.Forms.DialogResult.OK)return Task.FromResult(false);string target=Path.Combine(picker.SelectedPath,"Linux-export-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6));return ExportTo(selected,target);}}
  internal Task ExportTo(ExtEntry[] selected,string target){return Work(async token=>{var request=Request("export");request.Target=target;request.Paths=selected.Select(x=>x.Path).ToArray();var result=await Task.Run(()=>ExtReader.Call(request,token),token);Status.Text=L.Format("ext.exported",result.Completed,result.Skipped,target)+(result.Warnings!=null&&result.Warnings.Length>0?Environment.NewLine+String.Join(Environment.NewLine,result.Warnings):"");});}
  Task PreviewSelected(){var selected=Selected();if(selected.Length!=1||selected[0].Directory||!selected[0].Readable)return Task.FromResult(false);return Work(async token=>{var request=Request("preview");var temp=new ArchiveTemp(Path.Combine(AppPaths.ConfigDirectory,"ext-preview"));try{string name=selected[0].Name;ExtReader.WindowsName(name);request.Path=selected[0].Path;request.Target=Path.Combine(temp.Path,name);await Task.Run(()=>ExtReader.Call(request,token),token);var pane=new QuickPreviewPane(delegate{});var viewer=new Window{Owner=this,Title=L.Text("ext.preview"),Width=1000,Height=740,Content=pane,WindowStartupLocation=WindowStartupLocation.CenterOwner};FluentTheme.Dialog(viewer);ApplicationBrand.Attach(viewer);viewer.Closed+=delegate{pane.DisposePreview();temp.Dispose();};viewer.Show();pane.ShowFile(request.Target);Status.Text=L.Text("ext.readOnly");}catch{temp.Dispose();throw;}});}
